insert into public.learning_questions (id, stage_id, display_order, prompt, explanation)
values
  ('5365613b-3514-454b-af03-9f2b6fb4da8d', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 1, '백 묶음이 10개 모인 수는?', '백 묶음 10개는 100을 10번 모은 것이므로 1000입니다.'),
  ('fa4d9905-ccd3-4620-8682-74693da52eba', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 2, '1000이 3개 모인 수는?', '1000이 3개이면 1000+1000+1000이므로 3000입니다.'),
  ('34a6e215-3b95-481c-88af-293fb0524045', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 3, '3247을 바르게 읽은 것은?', '3247은 3000과 200과 40과 7로 이루어져 삼천이백사십칠이라고 읽습니다.'),
  ('bf3cb627-931c-415e-8b4b-f61ac050acd1', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 4, '사천오백육십이를 숫자로 쓴 것은?', '사천은 4000, 오백은 500, 육십은 60, 이는 2이므로 4562입니다.'),
  ('1a3f30a1-a3bc-4a6f-82a7-8b2390377b09', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 5, '5821에서 천의 자리 숫자는?', '5821의 천의 자리는 가장 왼쪽 자리이고 그 숫자는 5입니다.'),
  ('5fc61bee-3422-4fdd-8d12-ae671decf383', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 6, '4726에서 백의 자리 숫자 7이 나타내는 값은?', '7은 백의 자리에 있으므로 7백, 즉 700을 나타냅니다.'),
  ('5bb71624-5724-4f36-b8e2-2e69254d28ee', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 7, '천이 6개, 백이 3개, 십이 2개, 일이 5개인 수는?', '6000+300+20+5를 합하면 6325입니다.'),
  ('fd8970af-4896-4ee3-abfb-12afe7612e05', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 8, '7010을 바르게 읽은 것은?', '7010은 천이 7개, 백이 0개, 십이 1개, 일이 0개이므로 칠천십이라고 읽습니다.'),
  ('037d804e-133c-497a-b934-9c7be73b0056', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 9, '3052에서 0은 어느 자리에 있습니까?', '3052는 천의 자리 3, 백의 자리 0, 십의 자리 5, 일의 자리 2로 이루어집니다.'),
  ('9ba2ec43-6c70-4ea2-a392-f1be74de368f', 'f646b1de-ed3e-4975-9980-25008f8c5a6a', 10, '오천육을 숫자로 쓴 것은?', '오천육은 5000과 6을 합한 수이므로 백과 십의 자리에 0을 써서 5006입니다.'),
  ('772c1328-584a-4de6-aec2-b01bd95ad1d4', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 1, '4020을 천·백·십·일로 나타낸 것은?', '4020은 천 4개, 백 0개, 십 2개, 일 0개로 이루어집니다.'),
  ('66c928af-7917-4a3e-9e7f-5458763b1fc2', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 2, '6000+300+40+8을 하나의 수로 나타낸 것은?', '천 백 십 일의 값을 각 자리에 놓으면 6348입니다.'),
  ('e1ff22a3-a43e-4b31-93d8-7b55b5ef03e8', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 3, '7254를 바르게 분해한 것은?', '7254의 각 자리 값은 7000, 200, 50, 4이므로 이 값을 모두 더합니다.'),
  ('0670cd48-c983-4820-8266-734f5e2524da', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 4, '5006을 바르게 분해한 것은?', '5006은 천의 자리 값 5000과 일의 자리 값 6으로 이루어지고 백과 십의 값은 0입니다.'),
  ('88d5681c-454a-4c4c-a5a8-a400e82b2aa5', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 5, '다음 중 더 큰 수는? 4321, 3987', '천의 자리에서 4가 3보다 크므로 4321이 더 큽니다.'),
  ('90d2a44f-4158-4abc-a7ce-fc6587354399', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 6, '5608과 5630의 크기를 바르게 비교한 것은?', '천과 백의 자리는 같고 십의 자리에서 0이 3보다 작으므로 5608<5630입니다.'),
  ('c106d647-b5fa-4f12-b869-f2cfe6f0b24d', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 7, '1998 다음에 오는 수는?', '1998에 1을 더하면 1999이므로 바로 다음 수는 1999입니다.'),
  ('b79dfd71-feb0-40a5-a72f-1d13cb56e000', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 8, '3999 다음에 오는 수는?', '3999에 1을 더하면 천의 자리가 바뀌어 4000이 됩니다.'),
  ('aa5adf84-ab86-4c91-b447-18090e7d4939', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 9, '9□42에서 □가 백의 자리 숫자라면 □에 5를 넣은 수는?', '9□42의 백의 자리에 5를 넣으면 천 9, 백 5, 십 4, 일 2인 9542입니다.'),
  ('cd40645a-ca65-44e3-a77e-866a473f4737', '4de7cc6a-8fed-4d4e-acfb-00ec148f1154', 10, '8000+70+1을 숫자로 나타낸 것은?', '8000과 70과 1을 각 자리에 놓고 백의 자리에는 0을 써서 8071입니다.'),
  ('6e9fd626-d9ce-451d-9e2b-9d9ebe9410b5', '3d052fdd-93bf-4129-8f78-4f7e63160401', 1, '작은 수부터 차례로 나열한 것은? 3205, 3025, 3250', '천의 자리는 모두 3이고 백의 자리와 그다음 자리를 비교하면 3025<3205<3250입니다.'),
  ('f285db75-c8d0-4c88-a876-ab0b89f0c2c8', '3d052fdd-93bf-4129-8f78-4f7e63160401', 2, '큰 수부터 차례로 나열한 것은? 7010, 7100, 7001', '천의 자리는 같고 백과 십의 자리를 비교하면 7100>7010>7001입니다.'),
  ('fef7f6d8-551f-48d0-8a59-da214c4affee', '3d052fdd-93bf-4129-8f78-4f7e63160401', 3, '4□25가 4425보다 크고 4625보다 작을 때 □에 알맞은 숫자는?', '4425보다 크고 4625보다 작으려면 백의 자리 숫자는 4보다 크고 6보다 작은 5입니다.'),
  ('593a7129-09cf-4c95-a004-efe73ee48340', '3d052fdd-93bf-4129-8f78-4f7e63160401', 4, '3, 0, 5, 8 숫자 카드를 한 번씩 사용하여 가장 큰 네 자리 수를 만든 것은?', '가장 큰 수를 만들려면 큰 숫자부터 천 백 십 일의 자리에 놓아 8530을 만듭니다.'),
  ('00d3b241-3b4e-4209-835f-effdbbc6730f', '3d052fdd-93bf-4129-8f78-4f7e63160401', 5, '2, 0, 7, 4 숫자 카드를 한 번씩 사용하여 가장 작은 네 자리 수를 만든 것은?', '네 자리 수의 천의 자리에는 0을 쓸 수 없으므로 가장 작은 2를 앞에 놓고 나머지는 0,4,7 순서로 놓아 2047입니다.'),
  ('c52599e4-c7f3-4a7d-aa88-6fabad28d8ee', '3d052fdd-93bf-4129-8f78-4f7e63160401', 6, '6□08이 6508보다 클 때 □에 들어갈 수 있는 가장 작은 숫자는?', '천의 자리는 같고 백의 자리 숫자가 5보다 커야 하므로 가장 작은 숫자는 6입니다.'),
  ('5bd7c0eb-f4b1-4c10-81c6-16951dd5bd36', '3d052fdd-93bf-4129-8f78-4f7e63160401', 7, '어떤 수는 천이 4개, 십이 3개, 일이 9개이고 백은 없습니다. 이 수는?', '천 4개는 4000, 십 3개는 30, 일 9개는 9이고 백의 자리에 0을 써서 4039입니다.'),
  ('a17c19e4-890b-4513-af63-91e3b259ed60', '3d052fdd-93bf-4129-8f78-4f7e63160401', 8, '수 배열 4980, 4990, 5000, □에서 같은 규칙으로 이어질 수는?', '10씩 커지는 배열이므로 5000 다음 수는 5010입니다.'),
  ('f80a7337-bbc9-4972-979e-adadfa3838db', '3d052fdd-93bf-4129-8f78-4f7e63160401', 9, '5402와 5042를 비교할 때 가장 먼저 다른 자리는?', '천의 자리 5는 같고 백의 자리에서 4와 0이 처음 다르므로 백의 자리를 비교합니다.'),
  ('2793976f-ed6e-4c67-be7e-450e366d6c4e', '3d052fdd-93bf-4129-8f78-4f7e63160401', 10, '친구가 3052를 ''삼천오백이십''이라고 읽었습니다. 잘못 읽은 까닭은?', '3052는 백의 자리가 0이고 십의 자리가 5이며 일의 자리가 2이므로 삼천오십이라고 읽어야 합니다.'),
  ('774cec79-4513-428e-b909-6e963c19dada', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 1, '□205가 4205보다 크고 6205보다 작으며 천의 자리 숫자가 홀수일 때 가능한 수는?', '천의 자리 숫자는 4보다 크고 6보다 작은 홀수 5이므로 가능한 수는 5205입니다.'),
  ('628ea576-0015-457f-ae7a-8af355f75284', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 2, '1, 3, 0, 9를 한 번씩 사용해 3000보다 큰 가장 작은 수는?', '3000보다 크려면 천의 자리에 3을 놓고 남은 숫자를 작은 순서 0,1,9로 놓아 3019입니다.'),
  ('e6991067-bd8d-4801-8f08-f34427646830', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 3, '가장 큰 수부터 나열한 것은? 4020, 4200, 4002, 420', '네 자리 수가 세 자리 수보다 크고 네 자리 수끼리는 높은 자리부터 비교하여 4200>4020>4002>420입니다.'),
  ('d7696201-a8e8-4136-98c4-aa2656bd0776', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 4, '친구가 5074=5000+700+4라고 했습니다. 바르게 고친 설명은?', '5074에서 백의 자리는 0이고 7은 십의 자리이므로 5000+70+4로 분해합니다.'),
  ('d0bdecd9-332b-4832-9d4e-b56824cd17fa', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 5, '2, 4, 6, 8을 한 번씩 사용하여 5000보다 작은 가장 큰 수는?', '5000보다 작으려면 천의 자리에 4를 놓고 나머지를 큰 순서 8,6,2로 놓아 4862입니다.'),
  ('cf47fe5f-bebf-4ede-a12f-7998efe248d0', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 6, '4308<43□8이 되도록 □에 들어갈 수 있는 가장 작은 숫자는?', '천과 백의 자리는 같고 십의 자리에서 0보다 커야 하므로 가장 작은 숫자는 1입니다.'),
  ('d2569537-db19-4e64-9b6c-fb43367031bd', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 7, '9080, 9008, 9800을 비교한 설명 중 잘못된 것은?', '천의 자리는 모두 9이고 백의 자리에서 9800이 가장 큽니다. 9080은 십의 자리 8이 있어 9008보다 큽니다.'),
  ('a68bff06-b805-4e2f-88ec-d26fc8e09bc5', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 8, '어떤 수를 6000+□+20+5로 분해했습니다. 그 수가 6725라면 □는?', '6725는 6000+700+20+5이므로 백의 자리 값을 나타내는 □는 700입니다.'),
  ('fcfe2f99-8858-4c6a-9828-19b19450b2f9', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 9, '천의 자리 7, 일의 자리 6이고 백과 십의 자리 숫자의 합이 5인 가장 큰 수는?', '가장 크게 만들려면 백의 자리에 가능한 가장 큰 5를, 십의 자리에 0을 놓아 7506입니다.'),
  ('e158bc18-d93f-4b31-b494-3d07eceec5b2', 'bc44d9d9-489c-4b71-8188-7e29ec3d1f8f', 10, '수 카드 0, 2, 5, 7로 만든 네 자리 수 중 두 번째로 작은 수는?', '가장 작은 수는 2057이고 일의 자리 5와 7의 순서를 바꾼 2075가 두 번째로 작습니다.');

